draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // book
  ctx.fillStyle = 'black';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.rect(W/2-50, H/2-50, 100, 100);
  ctx.stroke();

  // lens
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2, H/2, 30+20*Math.sin(t), 0, 2*Math.PI);
  ctx.stroke();

  // focus lines
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(W/2, H/2-30-20*Math.sin(t));
  ctx.lineTo(W/2, H/2+30+20*Math.sin(t));
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2-30-20*Math.sin(t), H/2);
  ctx.lineTo(W/2+30+20*Math.sin(t), H/2);
  ctx.stroke();

  // stick figure
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2-100, H/2, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2-100, H/2+20);
  ctx.lineTo(W/2-100, H/2+50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2-100, H/2+50);
  ctx.lineTo(W/2-120, H/2+70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2-100, H/2+50);
  ctx.lineTo(W/2-80, H/2+70);
  ctx.stroke();

  ctx.restore();
}
